import {facts} from './facts-bank.js';import {editorialImage} from './editorial.js';import {icon3D as I} from './icons.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function factsPage(age,index=1){index=Number.isInteger(index)?Math.max(1,Math.min(300,index)):1;const f=facts[index-1];return `<section class="facts-experience"><a class="back" href="#/play">${I('arrow-left')}Back to Play</a><div class="page-intro"><div><span class="eyebrow">DID YOU KNOW? · AGES ${age}</span><h1>A little fact. A bigger world.</h1><p>300 discoveries, each written for three reading levels. Follow a surprise, then ask a new question.</p></div></div><article class="fact-discovery"><div class="fact-discovery-copy"><span class="eyebrow">DISCOVERY ${index} OF 300</span><h2>${esc(f.title)}</h2><p>${esc(f.levels[age])}</p><div class="reader-tools"><a class="button" href="#/discover/${f.id}">Open discovery ${I('book-open')}</a><button class="chip" data-action="age">${I('settings-2')}Reading level</button></div><a class="text-link" href="${esc(f.url)}" target="_blank" rel="noopener noreferrer" data-external="true">Reading reference · ${esc(f.source)} ${I('arrow-right')}</a></div>${editorialImage(f,true)}</article><nav class="fact-pagination" aria-label="Browse facts">${index>1?`<a class="chip" href="#/play/facts/${index-1}">${I('arrow-left')}Previous fact</a>`:'<span></span>'}<span>${index} / 300</span>${index<300?`<a class="chip" href="#/play/facts/${index+1}">Next fact ${I('arrow-right')}</a>`:'<a class="chip" href="#/discover/wows">Browse all facts</a>'}</nav><p class="reading-level">Take your time. There’s no timer, streak or penalty for stopping.</p></section>`}
